def apply_rule(grid):
    """For each row with 0s, change 4s to the right of last 0 into 1s"""
    result = [row[:] for row in grid]
    for i in range(len(result)):
        # Find positions of 0s
        zero_positions = [j for j in range(len(result[i])) if result[i][j] == 0]
        if zero_positions:
            # Find the rightmost 0
            last_zero_col = max(zero_positions)
            # Change 4s to the right of last 0 into 1s
            for j in range(last_zero_col + 1, len(result[i])):
                if result[i][j] == 4:
                    result[i][j] = 1
    return result

